solution.money.py:
from decimal import Decimal, ROUND_HALF_UP


def cents(value):
    # Decimal(str(...)) avoids binary-float drift; ROUND_HALF_UP rounds ties
    # away from zero, so negative half ties (e.g. -1.005) round to -101.
    amount = Decimal(str(value)) * 100
    return int(amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP))

